import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { MatAutocompleteModule, MatAutocompleteSelectedEvent } from '@angular/material/autocomplete';
import { MatChipInputEvent, MatChipsModule } from '@angular/material/chips';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatIconModule } from '@angular/material/icon';

const ALL_SUGGESTIONS = ['angular', 'material', 'typescript', 'rxjs'];

@Component({
  selector: 'app-tag-input',
  standalone: true,
  imports: [CommonModule, MatChipsModule, MatAutocompleteModule, MatFormFieldModule, MatIconModule],
  templateUrl: './tag-input.component.html',
})
export class TagInputComponent {
  tags: string[] = [];
  filteredSuggestions = ALL_SUGGESTIONS;

  addFromInput(event: MatChipInputEvent): void {
    const value = (event.value ?? '').trim();
    if (value) {
      this.tags.push(value);
    }
    event.chipInput?.clear();
  }

  addFromOption(event: MatAutocompleteSelectedEvent): void {
    this.tags.push(event.option.viewValue);
  }

  remove(tag: string): void {
    this.tags = this.tags.filter((t) => t !== tag);
  }
}
